import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useWishlist } from '../context/WishlistContext';
import { useAuth } from '../context/AuthContext';
import ProductCard from '../components/ProductCard';

const WishlistPage = () => {
  const { wishlist } = useWishlist();
  const { user } = useAuth();
  const navigate = useNavigate();

  if (!user) { navigate('/login'); return null; }

  return (
    <div className="page-fade">
      <div className="page-header"><div className="container"><h1>❤️ My Wishlist</h1></div></div>
      <div className="container">
        {wishlist.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 20px' }}>
            <div style={{ fontSize: 70, marginBottom: 16 }}>❤️</div>
            <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 24, color: 'var(--gray-600)', marginBottom: 12 }}>Your wishlist is empty</h2>
            <p style={{ color: 'var(--gray-400)', marginBottom: 24 }}>Save your favourite products here!</p>
            <Link to="/shop" className="btn-primary">🛒 Browse Products</Link>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 16 }}>
            {wishlist.filter(p => p._id).map(product => (
              <ProductCard key={product._id} product={product} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default WishlistPage;
